async function resetNativeHealth(){for(const kind of ['clients','lead_connections','health','leads','index','request_followthrough'])for(const path of await S.list(kind,''))await S.del(kind,path);}
const workerReceipt=async value=>S.put('health','leadConnections:lastRun',{at:new Date().toISOString(),ok:true,failures:0,...value});
