await check('Failed native scheduled recovery reports failure, retains its same work and clears only after actual recovery',async()=>{const f=await pendingNativeHealth(),worker=(await import('../netlify/functions/lead-connections-scheduler.mjs')).default,path=L.leadConnectionKey(f.c,'thumbtack'),before=await S.get('lead_connections',path),beforePosts=nativePosts;mode='foreign-business';const failed=await worker(),body=await failed.json();assert.equal(failed.status,503);assert.equal(body.ok,false);assert.equal(body.failures,1);assert.equal((await S.get('health','leadConnections:lastRun')).ok,false);assert.deepEqual((await S.get('lead_connections',path)).native.pendingNegotiations,before.native.pendingNegotiations);assert.equal((await T.thumbtackRecoveryHealth()).reasonCode,'thumbtack_recovery_failed');mode='';const repaired=await worker();assert.equal(repaired.status,200);assert.equal((await repaired.json()).ok,true);assert.equal((await T.thumbtackRecoveryHealth()).pending,0);assert.equal((await T.thumbtackRecoveryHealth()).ok,true);assert.equal(nativePosts,beforePosts);});
