await check('Public health requires explicit successful current blocks and a nonfuture bounded timestamp',async()=>{const publicHealth=(await import('../netlify/functions/health.mjs')).default,valid={at:new Date().toISOString(),ok:true,blocks:{tasks:{ok:true}}};for(const change of[{at:new Date(Date.now()+60000).toISOString()},{at:'invalid'},{at:new Date(Date.now()-25*60000-1000).toISOString()},{ok:undefined},{blocks:undefined},{blocks:[]},{blocks:{}},{blocks:{tasks:null}},{blocks:{tasks:{ok:false}}}]){await S.put('health','scheduler:lastRun',{...valid,...change});assert.equal((await publicHealth()).status,503);}await S.put('health','scheduler:lastRun',{...valid,at:new Date(Date.now()-25*60000+1000).toISOString()});assert.equal((await publicHealth()).status,200);});

await check('Partial history with an unseen newer customer or human message cannot select an automatic reply',async()=>{
 const AI=await import('../netlify/functions/lib/platform-ai.mjs'),originalProviderMessages=structuredClone(providerMessages);process.env.MC_PLATFORM_AI_ENABLED='1';
 try{for(const unseenFrom of ['Customer','Pro']){const f=await fixture();f.c.services=['Plumbing'];f.c.business.serviceArea=['Katy'];f.c.rules.hours={mon:{open:'08:00',close:'17:00'}};f.c.windows=['8 to 12'];await S.saveClient(f.c);await authorize(f);const view=(await L.leadConnectionsView(f.c)).thumbtack.automation;await AI.changePlatformAutomation(f.c,f.session,{action:'platform_automation',source:'thumbtack',operation:'enable',operationId:op(),expectedGeneration:f.connection.generation,expectedRevision:view.revision,rulesRevision:configurationRevision(f.c)});const row=await S.get('lead_connections',L.leadConnectionKey(f.c,'thumbtack')),at=Date.parse(row.native.automation.since);providerMessages=[{messageID:'519153481515696128',negotiationID:lead.negotiationID,from:'Customer',text:'Can you repair this sink?',attachments:[],sentAt:new Date(at+1000).toISOString()}];const unseen={messageID:'519153481515696129',from:unseenFrom,text:unseenFrom==='Pro'?'I have handled this myself.':'Cancel that request.',sentAt:new Date(at+2000).toISOString()};assert.ok(Date.parse(unseen.sentAt)>Date.parse(providerMessages[0].sentAt));const before=nativePosts,response=await incoming(f);assert.equal(response.status,200);const requestId=(await response.json()).id,source=await S.get('leads',`${f.c.slug}/${requestId}`);assert.equal(source.platform.context.historyComplete,false);const retained=await S.get('lead_connections',L.leadConnectionKey(f.c,'thumbtack')),thread=retained.native.automation.threads[requestId];assert.equal(thread.state,'history_unverified');assert.match(thread.reason,/history|conversation/i);assert.equal(AI.pendingPlatformAIRequest(retained),null);const outcome=await AI.runPlatformAITurn(f.c,requestId);assert.equal(outcome.processed,false);assert.equal(nativePosts,before);assert.equal(thread.turns.length,0);assert.equal(requests.filter(r=>r.host==='api.anthropic.com').length,0);/* A positive completeness signal here is an explicit internal contract fixture, never inferred from the real adapter. */await S.atomicUpdate('leads',`${f.c.slug}/${requestId}`,r=>({value:{...r,platform:{...r.platform,context:{...r.platform.context,historyComplete:true}}}}));await AI.notePlatformAIArrival(f.c,f.connection.generation,requestId);const allowed=await S.get('lead_connections',L.leadConnectionKey(f.c,'thumbtack'));assert.equal(allowed.native.automation.threads[requestId].state,'pending');assert.equal(AI.pendingPlatformAIRequest(allowed),requestId);await AI.changePlatformAutomation(f.c,f.session,{action:'platform_automation',source:'thumbtack',operation:'disable',operationId:op(),expectedGeneration:f.connection.generation,expectedRevision:AI.platformAIConnectionView(f.c,allowed).revision});}}
 finally{delete process.env.MC_PLATFORM_AI_ENABLED;providerMessages=originalProviderMessages;}
});


const sha=value=>createHash('sha256').update(typeof value==='string'?value:JSON.stringify(value)).digest('hex');
const staged=[];
function stage(f){staged.push({slug:f.c.slug,identity:W.workspaceTenant(f.c)});Object.assign(process.env,{THUMBTACK_STAGING_PARTNER_ENABLED:'1',THUMBTACK_STAGING_CLIENT_ID:'synthetic-stage-client',THUMBTACK_STAGING_CLIENT_SECRET:'synthetic-stage-secret',THUMBTACK_STAGING_SCOPES:'offline_access supply::fixture',THUMBTACK_STAGING_CLIENT_AUTH_METHOD:'client_secret_post',THUMBTACK_STAGING_TENANTS_JSON:JSON.stringify({version:1,expiresAt:new Date(Date.now()+3600000).toISOString(),tenants:staged})});}
const stored=f=>S.get('lead_connections',L.leadConnectionKey(f.c,'thumbtack'));
async function start(f){return T.startThumbtackConnection(f.c,f.session,{action:'start_thumbtack_connection',source:'thumbtack',expectedGeneration:f.connection.generation,operationId:op()});}
function legacyTokens(f,row,value={access_token:'fixture-access',refresh_token:'legacy-production-refresh',token_type:'Bearer',expires_in:3600}){const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',Buffer.from(process.env.THUMBTACK_TOKEN_ENCRYPTION_KEY,'hex'),iv);cipher.setAAD(Buffer.from(`${W.workspaceTenant(f.c)}:${row.native.generation}`));const bytes=Buffer.concat([cipher.update(JSON.stringify(value)),cipher.final()]);return {version:1,iv:iv.toString('hex'),tag:cipher.getAuthTag().toString('hex'),data:bytes.toString('base64')};}
await check('Exact staging cohort follows normal OAuth/webhook/Inbox path with explicit test-only projection and shared budget',async()=>{
 const f=await fixture();stage(f);const before=requests.length,link=await start(f),url=new URL(link.url);assert.equal(url.origin,'https://staging-auth.thumbtack.com');assert.equal(url.searchParams.get('client_id'),'synthetic-stage-client');
 await T.completeThumbtackConnection({state:url.searchParams.get('state'),code:'stage-owned-grant',endpointEnvironment:'staging'});let row=await stored(f);assert.deepEqual(row.native.providerBinding,{environment:'staging',clientIdHash:sha('synthetic-stage-client')});assert.equal(row.native.tokens.version,2);assert.equal(row.native.tokens.environment,'staging');assert.equal(row.native.tokens.clientIdHash,row.native.providerBinding.clientIdHash);
 const savedState=await S.get('lead_oauth_states',sha(JSON.stringify(url.searchParams.get('state'))));assert.equal(savedState.version,2);assert.deepEqual(savedState.providerBinding,row.native.providerBinding);assert(requests.slice(before).every(r=>r.origin.startsWith('https://staging-')));
 const response=await incoming(f);assert.equal(response.status,200);const id=(await response.json()).id,detail=await F.readRequestFollowthrough(f.c,f.session,id);assert.equal(detail.request.platform.environment,'staging');assert.match(detail.request.platform.label,/staging test/);assert.equal(detail.request.platform.context.historyComplete,false);
 const view=(await L.leadConnectionsView(f.c)).thumbtack;assert.equal(view.testEnvironment,true);assert.match(view.reason,/Staging test/);assert.equal(view.setup.providerURL,'https://staging-partner.thumbtack.com/');
 const keys=await S.list('lead_api_budget','');assert(keys.every(k=>/^thumbtack:\d{4}-\d{2}-\d{2}$/.test(k)));const budget=await S.get('lead_api_budget',keys[0]);assert(budget.tenants[W.workspaceTenant(f.c)]>0);
 const input={action:'send_platform_reply',requestId:id,sourceRevision:detail.request.sourceRevision,expectedGeneration:f.connection.generation,operationId:op(),text:'Owned staging reply'};const posts=nativePosts;await T.sendPlatformReply(f.c,f.session,input);await T.sendPlatformReply(f.c,f.session,input);assert.equal(nativePosts,posts+1);assert.equal(requests.at(-1).origin,'https://staging-api.thumbtack.com');
});
